(function(){
const pickers=document.querySelector('.reciter-pickers');
if(pickers&&!document.getElementById('ayah-play-mode')){
 const label=document.createElement('label');label.innerHTML='Ayet dinleme modu<select id="ayah-play-mode"><option value="auto">Otomatik · sonraki ayetlere devam et</option><option value="manual">Manuel · yalnızca seçili ayeti oku</option></select>';
 pickers.append(label);const select=label.querySelector('select');select.value=localStorage.getItem('ayah-play-mode')||'auto';select.onchange=()=>localStorage.setItem('ayah-play-mode',select.value);
}
function clearPlaying(){document.querySelectorAll('#verses .verse.is-playing').forEach(card=>card.classList.remove('is-playing'));}
const localAyahEditions={'ar.alafasy':{edition:'ar.alafasy',bitrate:128},'ar.abdulbasitmurattal':{edition:'ar.abdulbasitmurattal',bitrate:192},'ar.husary':{edition:'ar.husary',bitrate:128},'ar.minshawi':{edition:'ar.minshawi',bitrate:128},'ar.abdurrahmaansudais':{edition:'ar.abdurrahmaansudais',bitrate:192}};
function localAyahAudioUrl(surah,ayah,id){if(id==='yasser-surah')return `https://everyayah.com/data/Yasser_Ad-Dussary_128kbps/${String(surah.number).padStart(3,'0')}${String(ayah.number).padStart(3,'0')}.mp3`;const cfg=localAyahEditions[id]||localAyahEditions['ar.alafasy'];return `https://cdn.islamic.network/quran/audio/${cfg.bitrate}/${cfg.edition}/${ayah.global}.mp3`;}
function playFrom(startIndex){
 const surah=selectedSurah();if(!surah)return;const player=$('quran-audio'),mode=$('ayah-play-mode')?.value||'auto',reciter=$('arabic-reciter')?.value||'ar.alafasy';let index=startIndex;
 const next=()=>{if(index>=surah.ayahs.length){clearPlaying();setStatus(`${surah.name} suresinin seçilen bölümünün okuması tamamlandı.`);return;}const ayah=surah.ayahs[index],card=document.getElementById(`ayet-${ayah.number}`);clearPlaying();card?.classList.add('is-playing');card?.scrollIntoView({behavior:'smooth',block:'center'});player.src=localAyahAudioUrl(surah,ayah,reciter);player.hidden=false;player.load();player.play().catch(()=>{clearPlaying();setStatus('Ayet sesi başlatılamadı.');});setStatus(`${surah.name} ${ayah.number}. ayet okunuyor.`);index++;};
 player.onended=()=>{if(mode==='auto')next();else{clearPlaying();setStatus('Seçili ayetin okuması tamamlandı.');}};
 player.onerror=()=>{if(mode==='auto')setTimeout(next,250);else{clearPlaying();setStatus('Ayet sesi yüklenemedi.');}};
 next();
}
const verses=$('verses');if(verses)verses.addEventListener('click',event=>{const button=event.target.closest('[data-play-ayah]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();playFrom(Number(button.dataset.playAyah)-1);},true);
const chapterReciterIds={'ar.alafasy':7,'ar.abdulbasitmurattal':2,'ar.husary':6,'ar.minshawi':9,'ar.abdurrahmaansudais':3,'yasser-surah':97};
const playAll=$('play-arabic');if(playAll){playAll.addEventListener('click',clearPlaying,true);playAll.onclick=async()=>{const surah=selectedSurah();if(!surah)return;const reciter=$('arabic-reciter')?.value||'ar.alafasy',id=chapterReciterIds[reciter]||7,player=$('quran-audio');setStatus('Tam sure kaydı ve ayet zamanları hazırlanıyor…');try{const response=await fetch(`https://api.quran.com/api/v4/chapter_recitations/${id}/${surah.number}?segments=true`);if(!response.ok)throw new Error(String(response.status));const data=await response.json(),file=data.audio_file,times=file.timestamps||[];let active=-1;player.src=file.audio_url;player.hidden=false;player.ontimeupdate=()=>{const ms=player.currentTime*1000,index=times.findIndex(t=>ms>=t.timestamp_from&&ms<t.timestamp_to);if(index<0||index===active)return;active=index;clearPlaying();const number=Number(times[index].verse_key.split(':')[1]),card=document.getElementById(`ayet-${number}`);card?.classList.add('is-playing');card?.scrollIntoView({behavior:'smooth',block:'center'});};player.onended=()=>{clearPlaying();setStatus(`${surah.name} suresinin okuması tamamlandı.`);};player.onerror=()=>{clearPlaying();setStatus('Tam sure kaydı yüklenemedi.');};player.load();await player.play();setStatus(`${surah.name} suresi ayet takibiyle oynatılıyor.`);}catch(_){clearPlaying();setStatus('Tam sure kaydı başlatılamadı. Bağlantıyı denetleyin.');}};}
function bindHourlyDirect(){const button=$('hourly-open');if(!button||!state.corpus?.surahs?.length)return;const hour=Math.floor(Date.now()/3600000),global=Number((BigInt(hour)*2654435761n)%6236n)+1;let found,surah;for(const item of state.corpus.surahs){found=item.ayahs.find(ayah=>ayah.global===global);if(found){surah=item;break;}}if(!found||!surah)return;button.onclick=()=>{showPage('quran');selectSurah(surah.number,found.number);};}
setTimeout(bindHourlyDirect,1200);setInterval(bindHourlyDirect,60000);
})();
